// The service worker's logic, with everything it touches passed in so it can be
// tested under Node. sw.js (generated by site/sw.js.11ty.js) wires it to the
// real worker. Rules: docs/contracts.md section 9.
import { AUDIO_CACHE, SHELL_PREFIX, rangeResponse } from "./offline-core.mjs";

export function createWorker({ caches, fetch, origin, scope, buildId, precache, timeoutMs = 4000 }) {
  const shellName = `${SHELL_PREFIX}${buildId}`;

  const isAudio = (request, url) => request.destination === "audio" || /\.mp3$/i.test(url.pathname);
  const isLibrary = (url) => url.pathname.endsWith("/library.json");
  const isPage = (request) => request.mode === "navigate" || (request.headers.get("accept") ?? "").includes("text/html");

  function shouldHandle(request) {
    if (request.method !== "GET") return false;
    const url = new URL(request.url);
    if (isAudio(request, url)) return true;
    return url.origin === origin && url.pathname.startsWith(scope);
  }

  async function install() {
    const cache = await caches.open(shellName);
    try {
      await Promise.all(
        precache.map(async (url) => {
          // "reload" skips the HTTP cache, so GitHub Pages max-age cannot fill
          // the new cache with the previous build.
          const res = await fetch(url, { cache: "reload" });
          if (!res.ok || res.redirected) throw new Error(`precache ${url}: ${res.status}${res.redirected ? " (redirected)" : ""}`);
          await cache.put(url, res);
        }),
      );
    } catch (err) {
      // Never leave a half-filled shell cache: a retried install starts clean.
      await caches.delete(shellName).catch(() => {});
      throw err;
    }
  }

  async function activate() {
    for (const name of await caches.keys()) {
      if (name.startsWith(SHELL_PREFIX) && name !== shellName) await caches.delete(name);
    }
  }

  async function audioResponse(request) {
    const audio = await caches.open(AUDIO_CACHE);
    const hit = await audio.match(request.url, { ignoreVary: true });
    if (hit) return rangeResponse(hit, request.headers.get("range"));
    return fetch(request);
  }

  // Fire and forget: a failed or slow write (quota) must never hold up or break
  // the response. Only complete 200s are kept: never a 206, a 404 or a redirect.
  function keep(cache, request, res) {
    if (res.status !== 200 || res.redirected) return;
    try {
      const copy = res.clone();
      Promise.resolve(cache.put(request.url, copy)).catch(() => {});
    } catch {
      // ignore
    }
  }

  const TIMED_OUT = Symbol("timed out");

  async function networkFirst(request, { page = false, waitUntil } = {}) {
    const cache = await caches.open(shellName);
    // Exact URL first, then ignoring the query (?autoplay=1, router fetches, library.json?v=).
    const find = async () => (await cache.match(request.url)) ?? (await cache.match(request.url, { ignoreSearch: true }));
    const fallback = async (err) => {
      const hit = await find();
      if (hit) return hit;
      if (page) {
        const offline = await cache.match(`${origin}${scope}offline/`);
        if (offline) return offline;
      }
      throw err;
    };
    const network = Promise.resolve(fetch(request)).then((res) => {
      keep(cache, request, res);
      return res;
    });
    let timer;
    const slow = new Promise((resolve) => { timer = setTimeout(() => resolve(TIMED_OUT), timeoutMs); });
    let first;
    try {
      first = await Promise.race([network, slow]);
    } catch (err) {
      clearTimeout(timer);
      return fallback(err);
    }
    clearTimeout(timer);
    if (first !== TIMED_OUT) return first;
    // Slow: serve a copy if there is one (the fetch finishes in the background
    // and refreshes it); otherwise keep waiting for the real answer.
    const hit = await find();
    if (hit) {
      // Keep the worker alive until the background refresh finishes.
      const refresh = network.catch(() => {});
      if (waitUntil) waitUntil(refresh);
      return hit;
    }
    try {
      return await network;
    } catch (err) {
      return fallback(err);
    }
  }

  async function cacheFirst(request) {
    const cache = await caches.open(shellName);
    const hit = (await cache.match(request.url)) ?? (await cache.match(request.url, { ignoreSearch: true }));
    if (hit) return hit;
    const res = await fetch(request);
    keep(cache, request, res);
    return res;
  }

  function respond(request, waitUntil) {
    const url = new URL(request.url);
    if (isAudio(request, url)) return audioResponse(request);
    if (isLibrary(url)) return networkFirst(request, { waitUntil });
    if (isPage(request)) return networkFirst(request, { page: true, waitUntil });
    return cacheFirst(request);
  }

  return { install, activate, shouldHandle, respond, shellName };
}
